export interface Protocol {
  id: string;
  category: string;
  procedure: string;
  antibiotic: string;
  inductionDose: string;
  intraOp: string;
  duration: string;
  postOpInterval?: string;
  notes?: string;
}

export type TabType = 'adults' | 'guidelines';

export interface RenalDose {
  drug: string;
  normalDose: string;
  crcl50: string;
  crcl10_50: string;
  crcl_10: string;
  dialysis: string;
  notes?: string;
}

export type AppView = 'home' | 'prophylaxis' | 'renal';

import React, { useState, useMemo } from 'react';
import { Search, Info, AlertTriangle, ArrowLeft } from 'lucide-react';
import { renalDoses } from '../renalData';

interface RenalAdjustmentSectionProps {
  onBack: () => void;
}

const RenalAdjustmentSection: React.FC<RenalAdjustmentSectionProps> = ({ onBack }) => {
  const [search, setSearch] = useState('');

  const filteredDoses = useMemo(() => {
    return renalDoses.filter(d => 
      d.drug.toLowerCase().includes(search.toLowerCase())
    );
  }, [search]);

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
      <div className="flex items-center gap-2 mb-6">
        <button 
          onClick={onBack}
          className="p-2 hover:bg-gray-100 rounded-full transition-colors"
        >
          <ArrowLeft className="w-6 h-6 text-gray-600" />
        </button>
        <h2 className="text-xl font-bold text-gray-800">Antimicrobianos e Função Renal</h2>
      </div>

      <div className="relative mb-6">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <Search className="h-5 w-5 text-gray-400" />
        </div>
        <input
          type="text"
          className="block w-full pl-10 pr-3 py-3 border border-gray-300 rounded-xl leading-5 bg-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent shadow-sm"
          placeholder="Buscar antimicrobiano (ex: Meropenem, Vancomicina)"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      <div className="space-y-4">
        {filteredDoses.length === 0 ? (
          <div className="text-center py-12">
            <Info className="mx-auto h-12 w-12 text-gray-300" />
            <p className="mt-2 text-gray-500">Nenhum antimicrobiano encontrado.</p>
          </div>
        ) : (
          filteredDoses.map((item, idx) => (
            <div key={idx} className="bg-white border border-gray-200 rounded-xl shadow-sm overflow-hidden">
              <div className="bg-slate-50 px-4 py-3 border-b border-gray-200 flex justify-between items-center">
                <h3 className="font-bold text-slate-900">{item.drug}</h3>
                <span className="text-xs font-medium text-slate-500 uppercase tracking-wider">Ajuste de Dose</span>
              </div>
              <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <p className="text-xs font-bold text-gray-400 uppercase">Dose Normal (CrCl > 50)</p>
                  <p className="text-sm font-semibold text-blue-700">{item.normalDose}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-xs font-bold text-gray-400 uppercase">CrCl 10 - 50 mL/min</p>
                  <p className="text-sm font-medium text-gray-800">{item.crcl10_50}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-xs font-bold text-gray-400 uppercase">CrCl {'<'} 10 mL/min</p>
                  <p className="text-sm font-medium text-gray-800">{item.crcl_10}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-xs font-bold text-gray-400 uppercase">Hemodiálise</p>
                  <p className="text-sm font-medium text-gray-800">{item.dialysis}</p>
                </div>
              </div>
              {item.notes && (
                <div className="px-4 py-2 bg-yellow-50 border-t border-yellow-100 flex gap-2 items-start">
                  <AlertTriangle className="w-4 h-4 text-yellow-600 mt-0.5 flex-shrink-0" />
                  <p className="text-[11px] text-yellow-800">{item.notes}</p>
                </div>
              )}
            </div>
          ))
        )}
      </div>

      <div className="mt-8 bg-blue-50 p-4 rounded-xl border border-blue-100">
        <h4 className="font-bold text-blue-900 text-sm mb-2 flex items-center gap-2">
          <Info className="w-4 h-4" /> Importante
        </h4>
        <p className="text-xs text-blue-800 leading-relaxed">
          Os ajustes sugeridos são baseados em guias de referência. A decisão clínica deve considerar o estado volêmico, gravidade da infecção e monitorização laboratorial. O cálculo do CrCl deve ser feito preferencialmente pela fórmula de Cockcroft-Gault.
        </p>
      </div>
    </div>
  );
};

export default RenalAdjustmentSection;

import React, { useState, useMemo } from 'react';
import { BookOpen, Search, AlertCircle, ArrowLeft } from 'lucide-react';
import { protocols, categoryNotes } from '../data';
import { TabType } from '../types';
import SearchBar from './SearchBar';
import ProtocolTable from './ProtocolTable';
import CategoryFilter from './CategoryFilter';
import GeneralGuidelines from './GeneralGuidelines';

interface ProphylaxisSectionProps {
  onBack: () => void;
}

const ProphylaxisSection: React.FC<ProphylaxisSectionProps> = ({ onBack }) => {
  const [activeTab, setActiveTab] = useState<TabType>('adults');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('Todos');

  const categories = useMemo(() => {
    const cats = new Set(protocols.map((p) => p.category));
    return Array.from(cats).sort();
  }, []);

  const filteredProtocols = useMemo(() => {
    return protocols.filter((p) => {
      const matchesSearch =
        p.procedure.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.antibiotic.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.category.toLowerCase().includes(searchQuery.toLowerCase());

      const matchesCategory =
        selectedCategory === 'Todos' || p.category === selectedCategory;

      return matchesSearch && matchesCategory;
    });
  }, [searchQuery, selectedCategory]);

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-300 pb-10">
      <div className="flex items-center gap-2 mb-6">
        <button 
          onClick={onBack}
          className="p-2 hover:bg-gray-100 rounded-full transition-colors"
        >
          <ArrowLeft className="w-6 h-6 text-gray-600" />
        </button>
        <h2 className="text-xl font-bold text-gray-800">Antibioticoprofilaxia</h2>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden mb-6">
        <div className="flex border-b border-gray-200">
          <button
            onClick={() => setActiveTab('adults')}
            className={`flex-1 py-4 text-sm font-bold flex items-center justify-center gap-2 transition-all ${
              activeTab === 'adults'
                ? 'text-blue-600 bg-blue-50/50 border-b-2 border-blue-500'
                : 'text-gray-400 hover:text-gray-600'
            }`}
          >
            <Search className="w-4 h-4" />
            Protocolos
          </button>
          <button
            onClick={() => setActiveTab('guidelines')}
            className={`flex-1 py-4 text-sm font-bold flex items-center justify-center gap-2 transition-all ${
              activeTab === 'guidelines'
                ? 'text-blue-600 bg-blue-50/50 border-b-2 border-blue-500'
                : 'text-gray-400 hover:text-gray-600'
            }`}
          >
            <BookOpen className="w-4 h-4" />
            Diretrizes
          </button>
        </div>

        <div className="p-4 md:p-6">
          {activeTab === 'adults' && (
            <>
              <SearchBar value={searchQuery} onChange={setSearchQuery} />
              <CategoryFilter
                categories={categories}
                selectedCategory={selectedCategory}
                onSelect={setSelectedCategory}
              />

              <div className="mt-6">
                <ProtocolTable protocols={filteredProtocols} />

                {selectedCategory !== 'Todos' && categoryNotes[selectedCategory] && (
                  <div className="mt-4 bg-yellow-50 border border-yellow-200 rounded-xl p-4 flex items-start gap-3">
                    <AlertCircle className="w-5 h-5 text-yellow-600 mt-0.5 flex-shrink-0" />
                    <p className="text-xs text-yellow-800 whitespace-pre-line leading-relaxed">
                      {categoryNotes[selectedCategory]}
                    </p>
                  </div>
                )}
              </div>
            </>
          )}

          {activeTab === 'guidelines' && <GeneralGuidelines />}
        </div>
      </div>
    </div>
  );
};

export default ProphylaxisSection;

import React, { useState } from 'react';
import { AppView } from './types';
import Home from './components/Home';
import ProphylaxisSection from './components/ProphylaxisSection';
