import React, { useState } from 'react';
import { Home, Droplets, Calculator, Eraser, HeartPulse } from 'lucide-react';

interface GasometrySectionProps {
  onBack: () => void;
}

const InputField = ({ label, unit, value, onChange, placeholder, step = "any" }) => (
  <div>
    <label className="block text-sm font-bold text-gray-700 mb-1">{label} <span className="text-gray-400 font-normal">({unit})</span></label>
    <input
      type="number"
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      step={step}
      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent outline-none transition"
    />
  </div>
);

const GasometrySection: React.FC<GasometrySectionProps> = ({ onBack }) => {
  const [ph, setPh] = useState('');
  const [pco2, setPco2] = useState('');
  const [hco3, setHco3] = useState('');
  const [result, setResult] = useState<{ primary: string; secondary: string; color: string } | null>(null);

  const handleClear = () => {
    setPh('');
    setPco2('');
    setHco3('');
    setResult(null);
  };

  const handleCalculate = () => {
    const numPh = parseFloat(ph);
    const numPco2 = parseFloat(pco2);
    const numHco3 = parseFloat(hco3);

    if (isNaN(numPh) || isNaN(numPco2) || isNaN(numHco3)) {
      setResult({ primary: 'Valores Inválidos', secondary: 'Preencha todos os campos corretamente.', color: 'red' });
      return;
    }

    let primary = '';
    let secondary = '';
    let color = 'gray';

    const phNormal = [7.35, 7.45];
    const pco2Normal = [35, 45];
    const hco3Normal = [22, 26];

    if (numPh < phNormal[0]) { // Acidose
        color = 'red';
        const isMetabolic = numHco3 < hco3Normal[0];
        const isRespiratory = numPco2 > pco2Normal[1];

        if (isMetabolic && isRespiratory) {
            primary = 'Acidose Mista';
            secondary = 'Componentes metabólico e respiratório presentes.';
        } else if (isMetabolic) {
            primary = 'Acidose Metabólica';
            const expectedPco2 = (1.5 * numHco3) + 8;
            if (Math.abs(numPco2 - expectedPco2) <= 2) secondary = 'Com compensação respiratória adequada.';
            else if (numPco2 < expectedPco2 - 2) secondary = 'Com Alcalose Respiratória associada.';
            else secondary = 'Compensação inadequada ou Acidose Respiratória associada.';
        } else if (isRespiratory) {
            primary = 'Acidose Respiratória';
            const deltaPco2 = numPco2 - 40;
            const expectedHco3Acute = 24 + (0.1 * deltaPco2);
            if (numHco3 >= expectedHco3Acute - 2) secondary = 'Compensação metabólica presente (fase aguda).';
            else secondary = 'Descompensada ou com Acidose Metabólica associada.';
        } else {
            primary = 'Distúrbio Indeterminado';
            secondary = 'Valores conflitantes para acidose.';
        }
    } else if (numPh > phNormal[1]) { // Alcalose
        color = 'blue';
        const isMetabolic = numHco3 > hco3Normal[1];
        const isRespiratory = numPco2 < pco2Normal[0];

        if (isMetabolic && isRespiratory) {
            primary = 'Alcalose Mista';
            secondary = 'Componentes metabólico e respiratório presentes.';
        } else if (isMetabolic) {
            primary = 'Alcalose Metabólica';
            const expectedPco2 = (0.7 * numHco3) + 21;
            if (Math.abs(numPco2 - expectedPco2) <= 5) secondary = 'Com compensação respiratória.';
            else if (numPco2 > expectedPco2 + 5) secondary = 'Com Acidose Respiratória associada.';
            else secondary = 'Compensação inadequada ou Alcalose Respiratória associada.';
        } else if (isRespiratory) {
            primary = 'Alcalose Respiratória';
            const deltaPco2 = 40 - numPco2;
            const expectedHco3Acute = 24 - (0.2 * deltaPco2);
            if (numHco3 <= expectedHco3Acute + 2) secondary = 'Compensação metabólica presente (fase aguda).';
            else secondary = 'Descompensada ou com Alcalose Metabólica associada.';
        } else {
            primary = 'Distúrbio Indeterminado';
            secondary = 'Valores conflitantes para alcalose.';
        }
    } else { // pH Normal
        color = 'green';
        if (numPco2 > pco2Normal[1] && numHco3 > hco3Normal[1]) {
            primary = 'Distúrbio Compensado'; secondary = 'Sugestivo de Acidose Respiratória crônica ou Alcalose Metabólica.';
        } else if (numPco2 < pco2Normal[0] && numHco3 < hco3Normal[0]) {
            primary = 'Distúrbio Compensado'; secondary = 'Sugestivo de Alcalose Respiratória crônica ou Acidose Metabólica.';
        } else {
            primary = 'Gasometria Normal'; secondary = 'Parâmetros dentro da normalidade.';
        }
    }
    setResult({ primary, secondary, color });
  };

  const resultColors = {
    red: 'bg-red-500 border-red-600',
    blue: 'bg-blue-500 border-blue-600',
    green: 'bg-green-500 border-green-600',
    gray: 'bg-gray-500 border-gray-600',
  }

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-orange-50 rounded-xl flex items-center justify-center">
            <Droplets className="w-5 h-5 text-orange-600" />
          </div>
          <div>
            <h2 className="text-sm font-bold text-orange-700 uppercase leading-tight">Gasometria Arterial</h2>
            <p className="text-[10px] text-gray-400 font-medium uppercase">Calculadora & Guia</p>
          </div>
        </div>
        <button 
          onClick={onBack}
          className="p-2.5 bg-orange-50 text-orange-600 hover:bg-orange-100 rounded-full transition-colors flex items-center justify-center shadow-sm"
          title="Página Inicial"
        >
          <Home className="w-5 h-5" />
        </button>
      </div>

      <div className="bg-white rounded-2xl border border-gray-200 shadow-sm p-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
          <InputField label="pH" unit="" value={ph} onChange={setPh} placeholder="7.35 - 7.45" step="0.01" />
          <InputField label="PaCO₂" unit="mmHg" value={pco2} onChange={setPco2} placeholder="35 - 45" />
          <InputField label="HCO₃" unit="mEq/L" value={hco3} onChange={setHco3} placeholder="22 - 26" />
        </div>
        <div className="grid grid-cols-2 gap-3">
          <button onClick={handleClear} className="w-full bg-gray-200 hover:bg-gray-300 text-gray-800 py-3 rounded-lg font-bold flex items-center justify-center gap-2 transition-colors">
            <Eraser className="w-5 h-5" /> Limpar
          </button>
          <button onClick={handleCalculate} className="w-full bg-orange-500 hover:bg-orange-600 text-white py-3 rounded-lg font-bold flex items-center justify-center gap-2 transition-colors shadow">
            <Calculator className="w-5 h-5" /> Calcular
          </button>
        </div>
      </div>

      {result && (
        <div className="mt-6 animate-in fade-in">
          <div className={`text-white p-6 rounded-2xl shadow-lg border-b-4 ${resultColors[result.color]}`}>
            <div className="flex items-center gap-3 mb-2">
              <HeartPulse className="w-8 h-8"/>
              <h3 className="text-2xl font-extrabold tracking-tight">{result.primary}</h3>
            </div>
            <p className="text-sm font-medium opacity-90 pl-11">{result.secondary}</p>
          </div>
        </div>
      )}

    </div>
  );
};

