    be: { range: [-2, 2], interpretation: ['BE Negativo (Acidose)', 'Normal', 'BE Positivo (Alcalose)'] },
    so2: { range: [60, 75], interpretation: ['Saturação Baixa', 'Normal', 'Saturação Elevada'] },
  }
