const GasometrySection: React.FC<GasometrySectionProps> = ({ onBack }) => {
  const [gasometryType, setGasometryType] = useState('arterial');
  const [ph, setPh] = useState('');
  const [po2, setPo2] = useState('');
  const [pco2, setPco2] = useState('');
  const [hco3, setHco3] = useState('');
  const [be, setBe] = useState('');
  const [so2, setSo2] = useState('');
  const [analysisResult, setAnalysisResult] = useState(null);

  const handleClear = () => {
    setGasometryType('arterial');
    setPh('');
    setPo2('');
    setPco2('');
    setHco3('');
    setBe('');
    setSo2('');
    setAnalysisResult(null);
  };

  const handleCalculate = () => {
    const values = { ph, po2, pco2, hco3, be, so2 };
    const ranges = referenceRanges[gasometryType];
    const results: any = {};

    let hasRequiredValues = ph && pco2 && hco3;

    if (!hasRequiredValues) {
        setAnalysisResult({ error: 'Preencha pH, PCO₂ e HCO₃⁻ para a interpretação geral.' });
        return;
    }

    Object.keys(values).forEach(key => {
        const value = parseFloat(values[key]);
        const ref = ranges[key];
        let status = 'normal';
        if (!isNaN(value)) {
            if (value < ref.range[0]) status = 'low';
            else if (value > ref.range[1]) status = 'high';
        }
        results[key] = { status };
    });

    const numPh = parseFloat(ph);
    const numPco2 = parseFloat(pco2);
    const numHco3 = parseFloat(hco3);

    let primary = '';
    let secondary = '';

    if (results['ph'].status === 'low') { // Acidose
        const isMetabolic = results['hco3'].status === 'low';
        const isRespiratory = results['pco2'].status === 'high';

        if (isMetabolic && isRespiratory) primary = 'Acidose Mista';
        else if (isMetabolic) {
            primary = 'Acidose Metabólica';
            const expectedPco2 = (1.5 * numHco3) + 8;
            if (Math.abs(numPco2 - expectedPco2) <= 2) secondary = 'Compensada'; else secondary = 'Descompensada';
        } else if (isRespiratory) {
            primary = 'Acidose Respiratória';
            secondary = results['hco3'].status === 'high' ? 'Compensada' : 'Descompensada';
        } else primary = 'Sem distúrbio ácido-base primário detectado';
    } else if (results['ph'].status === 'high') { // Alcalose
        const isMetabolic = results['hco3'].status === 'high';
        const isRespiratory = results['pco2'].status === 'low';

        if (isMetabolic && isRespiratory) primary = 'Alcalose Mista';
        else if (isMetabolic) {
            primary = 'Alcalose Metabólica';
            const expectedPco2 = (0.7 * numHco3) + 21;
            if (Math.abs(numPco2 - expectedPco2) <= 5) secondary = 'Compensada'; else secondary = 'Descompensada';
        } else if (isRespiratory) {
            primary = 'Alcalose Respiratória';
            secondary = results['hco3'].status === 'low' ? 'Compensada' : 'Descompensada';
        } else primary = 'Sem distúrbio ácido-base primário detectado';
    } else { // pH Normal
        if ((results['pco2'].status === 'high' && results['hco3'].status === 'high') || (results['pco2'].status === 'low' && results['hco3'].status === 'low')) {
          primary = 'Distúrbio Misto Compensado';
        } else {
          primary = 'Sem distúrbio ácido-base primário detectado';
        }
    }

    results.general = { primary, secondary };
    setAnalysisResult(results);
  };

  return (
    <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-orange-50 rounded-xl flex items-center justify-center">
            <Droplets className="w-5 h-5 text-orange-600" />
          </div>
          <div>
            <h2 className="text-sm font-bold text-orange-700 uppercase leading-tight">Gasometria</h2>
            <p className="text-[10px] text-gray-400 font-medium uppercase">Calculadora & Guia</p>
          </div>
        </div>
        <button 
          onClick={onBack}
          className="p-2.5 bg-orange-50 text-orange-600 hover:bg-orange-100 rounded-full transition-colors flex items-center justify-center shadow-sm"
          title="Página Inicial"
        >
          <Home className="w-5 h-5" />
        </button>
      </div>

      <div className="bg-white rounded-2xl border border-gray-200 shadow-sm p-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
            <div>
              <label className="block text-sm font-bold text-gray-700 mb-1">Tipo de Gasometria:</label>
              <div className="relative">
                <select
                  value={gasometryType}
                  onChange={(e) => {setAnalysisResult(null); setGasometryType(e.target.value);}}
                  className="appearance-none w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent outline-none transition bg-white"
                >
                  <option value="arterial">Arterial</option>
                  <option value="venous">Venosa</option>
                </select>
                <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-700">
                  <ChevronDown className="h-4 w-4" />
                </div>
              </div>
            </div>
            <InputField name="ph" gasometryType={gasometryType} label="pH" unit="" value={ph} onChange={setPh} placeholder="Ex: 7.35" step="0.01" />
            <InputField name="po2" gasometryType={gasometryType} label="PO₂" unit="mmHg" value={po2} onChange={setPo2} placeholder="Ex: 83" />
            <InputField name="pco2" gasometryType={gasometryType} label="PCO₂" unit="mmHg" value={pco2} onChange={setPco2} placeholder="Ex: 40" />
            <InputField name="hco3" gasometryType={gasometryType} label="HCO₃⁻" unit="mmol/L" value={hco3} onChange={setHco3} placeholder="Ex: 24" />
            <InputField name="be" gasometryType={gasometryType} label="Base Excess (BE)" unit="" value={be} onChange={setBe} placeholder="Ex: 0" />
            <InputField name="so2" gasometryType={gasometryType} label="SO₂" unit="%" value={so2} onChange={setSo2} placeholder="Ex: 95" />
        </div>
        <div className="grid grid-cols-2 gap-3">
          <button onClick={handleClear} className="w-full bg-gray-200 hover:bg-gray-300 text-gray-800 py-3 rounded-lg font-bold flex items-center justify-center gap-2 transition-colors">
            <Eraser className="w-5 h-5" /> Limpar
          </button>
          <button onClick={handleCalculate} className="w-full bg-orange-500 hover:bg-orange-600 text-white py-3 rounded-lg font-bold flex items-center justify-center gap-2 transition-colors shadow">
            <Calculator className="w-5 h-5" /> Calcular
          </button>
        </div>
      </div>

      {analysisResult && (
        <div className="mt-6 animate-in fade-in">
          {analysisResult.error ? (
              <div className="p-4 rounded-lg flex items-center gap-3 bg-red-50 border-l-4 border-red-400">
                <AlertTriangle className="w-5 h-5 text-red-600"/>
                <p className="text-red-800 font-medium">{analysisResult.error}</p>
              </div>
          ) : (
            <div className="pt-2">
                <p className="font-bold text-gray-600 mb-2">Interpretação Geral</p>
                <div className={`p-4 rounded-lg flex items-start gap-3 ${analysisResult.general.primary.includes('Sem distúrbio') ? 'bg-green-50 border-green-400' : 'bg-red-50 border-red-400'} border-l-4`}>
                    <HeartPulse className={`w-5 h-5 mt-0.5 ${analysisResult.general.primary.includes('Sem distúrbio') ? 'text-green-700' : 'text-red-700'}`} />
                    <div>
                        <p className={`font-bold ${analysisResult.general.primary.includes('Sem distúrbio') ? 'text-green-800' : 'text-red-800'}`}>{analysisResult.general.primary}</p>
                        {analysisResult.general.secondary && <p className={`text-sm ${analysisResult.general.primary.includes('Sem distúrbio') ? 'text-green-700' : 'text-red-700'}`}>{analysisResult.general.secondary}</p>}
                    </div>
                </div>
            </div>
          )}
        </div>
      )}

      <div className="mt-8 pt-6 border-t border-gray-200">
        <h4 className="font-bold text-gray-700 mb-3 flex items-center gap-2"><BookOpen className="w-5 h-5 text-gray-500"/> Artigos de Referência</h4>
        <div className="space-y-3 text-sm">
            <a href="https://www.efdeportes.com/efd141/equilibrio-acido-basico-e-gasometria-arterial.htm" target="_blank" rel="noopener noreferrer" className="block bg-white p-4 rounded-lg border border-gray-200 hover:bg-gray-50 hover:border-gray-300 transition-colors">
                <p className="font-semibold text-blue-600">Equilíbrio ácido-básico e gasometria arterial: o que o profissional de educação física precisa saber</p>
                <p className="text-xs text-gray-500 mt-1">EFDeportes.com, Revista Digital. Buenos Aires - Año 15 - Nº 141 - Febrero de 2010.</p>
            </a>
            <a href="https://periodicos.furg.br/vittalle/article/view/11267" target="_blank" rel="noopener noreferrer" className="block bg-white p-4 rounded-lg border border-gray-200 hover:bg-gray-50 hover:border-gray-300 transition-colors">
                <p className="font-semibold text-blue-600">Interpretação de gasometria arterial</p>
                <p className="text-xs text-gray-500 mt-1">Gomes, E. B., & Pereira, H. C. P. (2021). Vittalle – Revista de Ciências da Saúde, 33(1), 203-218.</p>
