                 <DoseItem label="CrCl 10 - 50 mL/min" value={item.crcl10_50} isHighlighted={highlightedCategory === 'crcl10_50'} />
                 <DoseItem label="CrCl < 10 mL/min" value={item.crcl_10} isHighlighted={highlightedCategory === 'crcl_10'} />
